<?= $this->section('content') ?>
<div class="d-flex flex-column flex-md-row justify-content-between gap-3 mb-4"><div><h1 class="h3 section-title fw-bold">Categories</h1><p class="text-secondary mb-0">Organize the customer menu into clear sections.</p></div><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#categoryModal"><i class="bi bi-plus-lg me-1"></i>New category</button></div>
<div class="surface-card table-card overflow-hidden"><div class="table-responsive"><table class="table"><thead><tr><th>Name</th><th>Description</th><th>Order</th><th>Status</th><th class="text-end">Actions</th></tr></thead><tbody><?php foreach ($categories as $category): ?><tr><td class="fw-semibold"><?= esc($category['name']) ?></td><td><?= esc($category['description'] ?: '—') ?></td><td><?= esc($category['sort_order']) ?></td><td><span class="badge <?= $category['is_active'] ? 'text-bg-success' : 'text-bg-secondary' ?>"><?= $category['is_active'] ? 'Active' : 'Hidden' ?></span></td><td class="text-end"><button class="btn btn-sm btn-outline-primary" data-edit-category='<?= esc(json_encode($category),'attr') ?>'><i class="bi bi-pencil"></i></button><form class="d-inline" data-confirm="Remove this category?" action="<?= base_url('admin/categories/'.$category['id'].'/delete') ?>" method="post"><?= csrf_field() ?><button class="btn btn-sm btn-outline-danger"><i class="bi bi-trash"></i></button></form></td></tr><?php endforeach; ?></tbody></table></div></div>
